<template><view class="wish-page"><k-topbar title="筛选心愿" back :fab="false"/><view class="w-body"><text class="w-eyebrow">FIND YOUR LITTLE CONNECTION</text><text class="w-title">去哪里，帮个忙？</text><view class="w-card w-section"><text class="w-heading">帮忙地</text><input v-model="form.city" class="w-input w-section" placeholder="输入城市，如广西阳朔" maxlength="80"/><text class="w-caption">留空则查看所有城市，可输入省、市或地区。</text></view><text class="w-heading">互助方式</text><view class="w-pills w-section"><view v-for="t in modes" :key="t.key" class="w-pill" :class="{on:form.mode===t.key}" @click="form.mode=t.key">{{t.label}}</view></view><view class="w-section"><text class="w-heading">心愿分类</text><view class="wf-grid"><view v-for="c in categories" :key="c.key" class="wf-category" :class="{on:form.category===c.key}" @click="form.category=form.category===c.key?'':c.key"><k-icon :name="c.icon" :size="27" :color="form.category===c.key?'#3166f5':'#102c46'"/><view><text class="wf-category__title">{{c.label}}</text><text class="wf-category__hint">{{c.hint}}</text></view></view></view></view><view class="w-section"><text class="w-heading">展示价格区间</text><view class="w-row w-section"><input v-model="form.min" type="digit" class="w-input" placeholder="最低金额"/><text>—</text><input v-model="form.max" type="digit" class="w-input" placeholder="最高金额"/></view><text class="w-caption">按已含 1% 加价的展示价筛选，单位：元。</text></view><view class="w-section"><text class="w-heading">排序方式</text><view class="w-pills w-section"><view v-for="s in sorts" :key="s.key" class="w-pill" :class="{on:form.sort===s.key}" @click="form.sort=s.key">{{s.label}}</view></view></view><view class="w-field w-section" @click="go(route('rules'))"><k-icon name="info" :size="18" color="#102c46"/><text class="w-grow">查看品类规则</text><k-icon name="chevron-right" :size="18" color="#718095"/></view></view><view class="w-bottom"><button class="w-secondary" @click="reset">重置</button><button class="w-primary" @click="apply">查看心愿<k-icon name="arrow-right" :size="22" color="#e7f58a"/></button></view></view></template>
<script setup>
import { reactive } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { decodeQuery,go,back,toast } from '@/common/screen.js'
import { categories,route } from './wish.js'
const defaults={city:'',mode:'',category:'',min:'',max:'',sort:'latest'},form=reactive({...defaults})
const modes=[{key:'',label:'全部'},{key:'paid',label:'有偿'},{key:'free',label:'免费'}],sorts=[{key:'latest',label:'最新发布'},{key:'deadline',label:'即将到期'},{key:'price',label:'价格从低到高'}]
onLoad(q=>{let raw=decodeQuery(q).value||'{}';for(let n=0;n<3;n++){try{const saved=JSON.parse(raw);for(const key of Object.keys(defaults))if(typeof saved[key]==='string')form[key]=saved[key];break}catch(e){try{raw=decodeURIComponent(raw)}catch(e){break}}}})
function reset(){Object.assign(form,defaults)}
function apply(){if(['min','max'].some(k=>form[k]!==''&&(!/^\d+(\.\d{1,2})?$/.test(form[k])||Number(form[k])>101000))){toast('请输入有效的价格，最多两位小数');return}if(form.min!==''&&form.max!==''&&Number(form.min)>Number(form.max)){toast('最低金额不能高于最高金额');return}uni.$emit('wish:filter',{...form});back()}
</script>
<style lang="scss">@import './wish.scss';.wf-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px}.wf-category{display:flex;gap:10px;align-items:center;background:white;border:1px solid #e3e9f3;border-radius:14px;padding:15px 11px}.wf-category.on{background:#eaf0ff;border-color:#3166f5}.wf-category__title{display:block;font-size:13px;font-weight:750}.wf-category__hint{display:block;font-size:9px;color:#718095;margin-top:3px}.wf-category>view{min-width:0}</style>
